"""Build the Ukrainian phase-3 report and validation-only scientific figure."""
from __future__ import annotations
import csv
import json
from pathlib import Path
import shutil
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
from prepare_data import ROOT,DOCS,sha256
from run_phase3 import WORK,write_json

DATA_URL='https://data.melbourne.vic.gov.au/explore/dataset/on-street-car-parking-sensor-data-2019/information/'
S2='https://doi.org/10.1109/TCOMM.2022.3160563'

def make_report(work=WORK):
    r=json.loads((work/'tuning-results.json').read_text(encoding='utf-8'))
    cohort=json.loads((work/'tuning-cohort.json').read_text(encoding='utf-8'))
    train=json.loads((work/'models/training-metadata.json').read_text(encoding='utf-8'))
    verification=json.loads((DOCS/'phase3-verification.json').read_text(encoding='utf-8'))
    published=json.loads((work/'s2-published-example-verification.json').read_text(encoding='utf-8'))
    candidates={x['name']:x for x in r['candidates']}
    metrics={name:x['metrics'] for name,x in candidates.items()}
    reference=metrics['fixed_60'];c2=r['resource_selection']['1440']['C2']['policy'];c2metrics=metrics[c2]
    figures=DOCS/'figures';figures.mkdir(exist_ok=True)
    plt.rcParams.update({'font.family':'DejaVu Sans','font.size':10,'axes.spines.top':False,'axes.spines.right':False,'svg.fonttype':'none'})
    fig,axes=plt.subplots(1,3,figsize=(14,5.6),layout=None)
    panels=[('false_free_seconds_per_bay_day','Помилково «вільно», с/місце/добу'),
      ('false_occupied_seconds_per_bay_day','Помилково «зайнято», с/місце/добу'),
      ('M60','Повністю пропущені звільнення ≥60 с, %')]
    groups=[('fixed','Регулярні перевірки','#4b5563','o'),('state','Два інтервали за останнім станом','#7c3aed','s'),
      ('C2','C1 / C2 (вибрані точки збіглися)','#0284c7','D'),('S2','Адаптація методу S2','#ea580c','^')]
    for family,label,color,marker in groups:
        if family=='fixed':
            names=[f'fixed_{d}' for d in (30,45,60,75,90,120,180,240,300)]
        else:names=[r['resource_selection'][str(b)][family]['policy'] for b in (720,1440,2880)]
        values=sorted((metrics[n] for n in names if n),key=lambda m:m['samples_per_bay_day'])
        x=[m['samples_per_bay_day'] for m in values]
        for ax,(key,ylabel) in zip(axes,panels):
            y=[100*m['vacancy_duration_profiles']['60']['missed_fraction'] if key=='M60' else m[key] for m in values]
            ax.plot(x,y,color=color,marker=marker,lw=1.5,ms=6,label=label)
